<script>(()=>{const nav=document.querySelector('[data-f408-nav]');document.querySelector('[data-f408-menu-toggle]')?.addEventListener('click',()=>nav?.classList.toggle('is-open'));document.querySelector('[data-f408-search]')?.addEventListener('click',()=>document.querySelector('[data-f408-search-panel]')?.classList.toggle('is-open'));const els=[...document.querySelectorAll('[data-f408-reveal]')];if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.1,rootMargin:'0px 0px -35px'});els.forEach(el=>observer.observe(el))}else els.forEach(el=>el.classList.add('is-visible'));document.querySelectorAll('[data-f408-slider]').forEach(slider=>{const slides=[...slider.querySelectorAll('[data-f408-slide]')];if(slides.length<2)return;let active=0,timer;const show=n=>{active=(n+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('is-active',i===active))};const play=()=>{clearInterval(timer);timer=setInterval(()=>show(active+1),5200)};slider.querySelector('[data-f408-prev]')?.addEventListener('click',()=>{show(active-1);play()});slider.querySelector('[data-f408-next]')?.addEventListener('click',()=>{show(active+1);play()});play()})})();</script>
